begin transaction read only;
do $proof$
declare v_farm constant uuid := '27010000-0000-4000-8000-000000000005'; v_owner constant uuid := '27000000-0000-4000-8000-000000000001';
begin
 if (select count(*) from public.application_records where farm_id=v_farm) <> 1 or not exists (select 1 from public.application_records where id='27043000-0000-4000-8000-000000000005' and farm_id=v_farm and field_id='27020000-0000-4000-8000-000000000005' and crop_assignment_id='27030000-0000-4000-8000-000000000005' and status='completed' and application_date='2027-07-07' and start_time='13:20' and applied_acres=40 and target_pest='Synthetic broadleaf' and applicator_name_snapshot='Scenario Operator' and applicator_license_number_snapshot='PRESENCE-ONLY-2027' and wind_speed_mph=8 and wind_direction='SW' and temperature_f=74 and relative_humidity_pct=52) then raise exception 'CC application is not exact'; end if;
 if (select count(*) from public.application_products where farm_id=v_farm) <> 1 or not exists (select 1 from public.application_products where id='27044000-0000-4000-8000-000000000005' and application_id='27043000-0000-4000-8000-000000000005' and product_id='27040000-0000-4000-8000-000000000005' and product_kind_snapshot='chemical' and product_name_snapshot='Synthetic Cedar Herbicide 41' and epa_registration_number_snapshot='00000-005' and is_restricted_use_snapshot=false and signal_word_snapshot='caution' and restricted_entry_interval_hours_snapshot=12 and preharvest_interval_hours_snapshot=0 and max_label_rate_snapshot=.125 and max_label_rate_unit_snapshot='gal' and max_label_rate_basis_snapshot='acre' and rate=.125 and total_quantity=5 and quantity_in_inventory_unit=5) then raise exception 'CC application product is not exact'; end if;
 if (select on_hand_quantity from public.inventory_on_hand where farm_id=v_farm and product_id='27040000-0000-4000-8000-000000000005') <> 15 then raise exception 'CC inventory did not reconcile from 20.00 to 15.00'; end if;
 if (select count(*) from public.scouting_notes where farm_id=v_farm) <> 1 or not exists(select 1 from public.scouting_notes where id='27060000-0000-4000-8000-000000000005' and field_id='27020000-0000-4000-8000-000000000005' and observed_on='2027-07-07' and category='weed' and note='Synthetic waterhemp along west edge' and latitude is null and longitude is null) then raise exception 'CC scouting note is not exact'; end if;
 if (select count(*) from public.repository_write_receipts where farm_id=v_farm and operation_id='27094000-0000-4000-8000-000000000005' and user_id=v_owner and result->>'id'='27060000-0000-4000-8000-000000000005' and result->'photos'='[]'::jsonb and not(result ? 'created_task_id')) <> 1 then raise exception 'CC scouting receipt is not exact'; end if;
 if exists(select 1 from public.scouting_photos) or exists(select 1 from public.farm_tasks) or exists(select 1 from public.notifications) or exists(select 1 from public.inventory_adjustments) or exists(select 1 from public.programs) or exists(select 1 from public.production_estimates) or exists(select 1 from public.grain_contracts) or exists(select 1 from public.spray_window_states) or exists(select 1 from public.push_deliveries) or exists(select 1 from public.push_delivery_targets) then raise exception 'CC named non-write fence changed'; end if;
 if (select count(*) from public.inventory_receipts) <> 1 or (select count(*) from public.inventory_receipt_lines) <> 1 or (select count(*) from public.application_records) <> 1 or (select count(*) from public.application_products) <> 1 or (select count(*) from public.scouting_notes) <> 1 or (select count(*) from public.repository_write_receipts) <> 1 then raise exception 'CC duplicate/replay fence changed write cardinality'; end if;
end $proof$;
select 'CEDAR_CREEK_2027_VERIFY_PASS'; rollback;
